def _graph(unitcell):
    """Graph based unitcell geometry"""

    # Pull out unitcell definition
    try:
        # Check for standard definition
        definition = GRAPH_DEF[unitcell]
        padding = _GRAPH_PADDING[unitcell]
    except TypeError:
        # Assume custom definition
        padding = unitcell.pop("padding", 0)
        definition = unitcell
    try:
        nodes = definition["node"]
        beams = definition["beam"]
        faces = definition["face"]
        if isinstance(nodes, np.ndarray):
            nodes = {
                f"{i}": {d: v for d, v in zip("xyz", vs)} for i, vs in enumerate(nodes)
            }
        if isinstance(beams, np.ndarray):
            beams = {
                f"{i}": {f"n{n+1}": f"{v}" for n, v in enumerate(vs)}
                for i, vs in enumerate(beams)
            }
        if isinstance(faces, np.ndarray):
            faces = {
                f"{i}": {f"n{n+1}": f"{v}" for n, v in enumerate(vs) if v >= 0}
                for i, vs in enumerate(faces) 
            }
    except:
        raise ValueError(
            "Input unitcell appears to be a custom definition, "
            "but isn't definted correct. Should be a dictionary "
            f"with keys 'node', 'beam', and 'face', not {definition}."
        )

    def f(L, W, H, t, smoothing=0):
        # Define unitcell scaling
        scaling = np.array([L, W, H])

        # Create beam-based objects
        r = t / 2
        geom1 = None
        geom2s = []
        for v in beams.values():
            z1, z2 = [
                np.array([float(nodes[str(subv)][d]) for d in "xyz"]) * scaling
                for subv in v.values()
            ]

            tmp = sdf.capsule(z1, z2, r).repeat([L, W, H], padding=padding)
            if not geom1:
                geom1 = tmp
            else:
                geom2s.append(tmp)

        # Create plate-based objects
        for v in faces.values():
            pts = [
                np.array([float(nodes[str(subv)][d]) for d in "xyz"]) * scaling
                for subv in v.values()
            ]

            tmp = _plate(pts, t).repeat([L, W, H], padding=padding)
            if not geom1:
                geom1 = tmp
            else:
                geom2s.append(tmp)

        # Combine all of the geometry
        if geom2s:
            if not (smoothing > 0):
                smoothing = None
            geom = geom1.union(*geom2s, k=smoothing)
        else:
            geom = geom1

        return geom

@sdf.sdf3
def _iwp(L, W, H):
    def f(p):
        X = PI2 / L * p[:, 0]
        Y = PI2 / W * p[:, 1]
        Z = PI2 / H * p[:, 2]

        # Define the nominal implicit function
        phi = 2 * (cos(X) * cos(Y) + cos(Y) * cos(Z) + cos(Z) * cos(X)) - (
            cos(2 * X) + cos(2 * Y) + cos(2 * Z)
        )

        # Calculate the gradient of the implicit function to convert to
        # sign distance function
        dphidx = PI2 / L * (-2 * sin(X) * cos(Y) - 2 * sin(X) * cos(Z) + 2 * sin(2 * X))
        dphidy = PI2 / W * (-2 * sin(Y) * cos(X) - 2 * sin(Y) * cos(Z) + 2 * sin(2 * Y))
        dphidz = PI2 / H * (-2 * sin(Z) * cos(X) - 2 * sin(Z) * cos(Y) + 2 * sin(2 * Z))
        norm = np.sqrt(dphidx**2 + dphidy**2 + dphidz**2)

        return _tpms2sdf(phi, norm)

    return f


